<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import { getMunicipalities, getSettlements, getStates, lookupPostalCode, type LocationOption, type SettlementOption } from '../services/locations'

const state = defineModel<string>('state', { required: true })
const municipality = defineModel<string>('municipality', { required: true })
const neighborhood = defineModel<string>('neighborhood', { required: true })
const postalCode = defineModel<string>('postalCode', { required: true })
type AddressValidation = { state?: string; municipality?: string; neighborhood?: string; postalCode?: string; force?: boolean }
const props = defineProps<{ showIcons?: boolean; validation?: AddressValidation; resetToken?: number }>()
const states = ref<LocationOption[]>([]); const municipalities = ref<LocationOption[]>([]); const settlements = ref<SettlementOption[]>([])
const stateId = ref(''); const municipalityId = ref(''); const loading = ref(false); const error = ref(''); let request = 0
const touched = ref<Record<string, boolean>>({ state: false, municipality: false, neighborhood: false, postalCode: false })
function touch(field: string) { touched.value[field] = true }
function validationMessage(field: 'state' | 'municipality' | 'neighborhood' | 'postalCode') { return props.validation?.force || touched.value[field] ? props.validation?.[field] || '' : '' }
function resetAddress() { request += 1; loading.value = false; error.value = ''; stateId.value = ''; municipalityId.value = ''; municipalities.value = []; settlements.value = []; state.value = ''; municipality.value = ''; neighborhood.value = ''; postalCode.value = ''; touched.value = { state: false, municipality: false, neighborhood: false, postalCode: false } }
const clearFromState = () => { municipality.value=''; neighborhood.value=''; postalCode.value=''; municipalityId.value=''; municipalities.value=[]; settlements.value=[] }
async function selectState(id: string) { clearFromState(); stateId.value=id; state.value=states.value.find(x=>x.id===id)?.name || ''; if(!id)return; const current=++request; loading.value=true; try { const rows=await getMunicipalities(id); if(current===request) municipalities.value=rows } catch { error.value='No pudimos consultar los municipios. Intenta nuevamente' } finally { if(current===request) loading.value=false } }
async function selectMunicipality(id: string) { neighborhood.value=''; postalCode.value=''; municipalityId.value=id; municipality.value=municipalities.value.find(x=>x.id===id)?.name || ''; settlements.value=[]; if(!id)return; const current=++request; loading.value=true; try { const rows=await getSettlements(stateId.value,id); if(current===request) settlements.value=rows } catch { error.value='No pudimos consultar las localidades. Intenta nuevamente' } finally { if(current===request) loading.value=false } }
function selectSettlement(id: string) { const row=settlements.value.find(x=>x.id===id); neighborhood.value=row?.name || ''; postalCode.value=row?.postal_code || '' }
async function findPostal() { if(!/^\d{5}$/.test(postalCode.value)){error.value='El código postal debe tener cinco dígitos.';return}; const current=++request; const previousNeighborhood=neighborhood.value; loading.value=true; error.value=''; try { const data=await lookupPostalCode(postalCode.value); if(current!==request)return; stateId.value=data.state.id; state.value=data.state.name; municipalities.value=await getMunicipalities(data.state.id); municipalityId.value=data.municipality.id; municipality.value=data.municipality.name; settlements.value=data.settlements; const matchingSettlement=data.settlements.find(item=>item.name===previousNeighborhood); neighborhood.value=matchingSettlement?.name || (data.settlements.length===1 ? data.settlements[0].name : '') } catch (e:any) { if(current===request) error.value=e.response?.status===404?'No encontramos información para este código postal':'No pudimos consultar las localidades. Intenta nuevamente' } finally { if(current===request) loading.value=false } }
async function hydrateExistingAddress() { const existingState=states.value.find(item=>item.name===state.value); if(!existingState) { if(/^\d{5}$/.test(postalCode.value)) await findPostal(); return }; stateId.value=existingState.id; municipalities.value=await getMunicipalities(existingState.id); const existingMunicipality=municipalities.value.find(item=>item.name===municipality.value); if(!existingMunicipality) { if(/^\d{5}$/.test(postalCode.value)) await findPostal(); return }; municipalityId.value=existingMunicipality.id; settlements.value=await getSettlements(existingState.id,existingMunicipality.id); if(neighborhood.value && !settlements.value.some(item=>item.name===neighborhood.value)) settlements.value.unshift({ id:`saved-${neighborhood.value}`, name:neighborhood.value, postal_code:postalCode.value, type:'Ubicación registrada' }) }
onMounted(async()=>{try{states.value=await getStates(); await hydrateExistingAddress()}catch{error.value='No pudimos consultar los estados. Intenta nuevamente'}})
watch(() => props.resetToken, resetAddress)
watch(error, value => { if(value) setTimeout(()=>{ if(error.value===value) error.value='' }, 5000) })
</script>
<template>
  <v-alert v-if="error" type="warning" variant="tonal" density="compact" class="mb-4">{{ error }}</v-alert>
  <v-row><v-col cols="12" md="6"><v-select v-model="stateId" label="Estado *" placeholder="Selecciona un estado" :prepend-inner-icon="props.showIcons ? 'mdi-map-outline' : undefined" :items="states" item-title="name" item-value="id" variant="outlined" density="comfortable" :menu-props="{ class: 'location-options-menu', contentClass: 'location-options-menu' }" :loading="loading" :error-messages="validationMessage('state')" @blur="touch('state')" @update:model-value="selectState"/></v-col><v-col cols="12" md="6"><v-select v-model="municipalityId" label="Municipio o alcaldía *" placeholder="Primero selecciona un estado" :prepend-inner-icon="props.showIcons ? 'mdi-city-variant-outline' : undefined" :items="municipalities" item-title="name" item-value="id" variant="outlined" density="comfortable" :menu-props="{ class: 'location-options-menu', contentClass: 'location-options-menu' }" :disabled="!stateId" :loading="loading" :error-messages="validationMessage('municipality')" @blur="touch('municipality')" @update:model-value="selectMunicipality"/></v-col><v-col cols="12" md="6"><v-autocomplete :model-value="settlements.find(x=>x.name===neighborhood)?.id || null" label="Colonia o localidad *" placeholder="Primero selecciona un municipio" :prepend-inner-icon="props.showIcons ? 'mdi-home-map-marker' : undefined" :items="settlements" item-title="name" item-value="id" :item-props="x=>({subtitle:`${x.type} · CP ${x.postal_code}`})" variant="outlined" density="comfortable" :menu-props="{ class: 'location-options-menu', contentClass: 'location-options-menu' }" :disabled="!municipalityId" :loading="loading" :error-messages="validationMessage('neighborhood')" @blur="touch('neighborhood')" @update:model-value="selectSettlement"/></v-col><v-col cols="12" md="6"><v-text-field v-model.trim="postalCode" label="Código postal *" placeholder="Ej. 42860" prepend-inner-icon="mdi-mailbox-outline" variant="outlined" density="comfortable" maxlength="5" :loading="loading" :error-messages="validationMessage('postalCode')" @blur="touch('postalCode')" @keydown.enter.prevent="findPostal"/></v-col></v-row>
</template>
